INSERT INTO membrane_retrofits(assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES
('A088-01','R088-01','CN0134','acceptance2022','screening',3,'金属回收及深度回用','维持金属回收，核实芬顿后残余氧化剂及生化出水有机物/盐，按回用目标试UF/RO；浓液处置先落实','conditional','现行水质、水量、回用需求、浓液及安全合规','图4-1/2历史工艺，候选为推断','历史站非现行实装证明','分股实际流量、TDS、金属、残余氧化剂、膜试验、费用','多工况采样、物料衡算、连续小试、全成本对比','优化已有芬顿生化及金属回收',NULL,NULL,NULL,NULL,NULL,NULL,'缺现行实测不评分','2026-11-28');
INSERT INTO evidence_notes(note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES
('N088-01','CN0134','W03S03','原图补核及重复纠偏','图4-1、4-2截图；3.4','038已存64监测、10万元废水专项投资及监测日产量；本轮不重复。新项目3770.6t/a、原1756、全厂5526.6为报告核算非全年计量；总用水3668与新项目排水量关系待核。图4-2明确芬顿、物化沉淀、缺氧中沉、好氧二沉、压滤滤液回流。隔膜泵非膜。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N088-02','CN0240','S043-01','历史调试产量及原辅料','表3.3-1、3.3-2印刷页12','建成总规模80000m³/a；2018调试15851.074m³，116.6m³/d，43.7%负荷。原料蜂窝7529t、平板396t；20%稀硫酸1458.3t，乳化剂3.49t，渗透剂3.01t，偏钒酸铵30.43t，钛溶胶427.98t，玻纤4.92t，30%双氧水6.82t。为生产线原辅料，不是污水药耗。表格文字可读，截图超时。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N088-03','CN0240','S043-01','历史生产用能与耗水','表3.3-2','2018调试水21414.8m³（1.351m³/m³产品）、电3063394kWh（193.26kWh/m³产品）、天然气1607963m³（101.44m³/m³产品）。整体生产线消耗，不可归入污水运营成本；年口径92419m³另为表3.4-1。旧排水总计矛盾已在N043-06记录。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N088-04','CN0235','W07S17','分期接管总量核定','批复第3条','一期1620t/a、二期建成后全厂3240t/a上限；5项污染物年总量分别入库。工艺水全回用为设计要求，浓水去向未披露；500m³事故池非处理能力，废UF/RO膜危废委外。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N088-05','CN0359','S088-01','综合许可边界','官方公示第3行索引','HW省1404230100，2025-05-20至2030-05-19，8万t/a综合含HW50；原页复开403，不能将全部许可当废催化剂分项。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N088-06','CN0359','S088-02','废催化剂线规模','政府报道','5万t/a废催化剂线，非实际接收或许可证独立分项。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N088-07','CN0359','S088-10','工艺和厂址','清单第528行','古韩镇、电熔炉生产线；未获湿法水工艺和污水站实际量。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N088-08','CN0360','S088-03','开工','政府报道','2024-12签约，2025-03开工，项目5000t/a。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N088-09','CN0360','S088-04','相邻产业关系','2026-04-21报道索引','报道收尾施工，回收钯镍拟供催化剂产业；不确认已投运、实际成交或共用污水设施。','WEB_SECONDARY','WEB_TEXT','2026-11-28'),
('N088-10','CN0361','S088-05','发改核准','云发改核准〔2023〕2号','项目代码2211-445381-04-01-460388；废催化剂6000t/a，其他工业含贵金属固废65、珠宝200、粗金2470t/a；发改核准非环评及经营许可。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N088-11','CN0361','S088-06','工程竣工节点','2026-03-11政府报道','报道竣工验收，文字仍为建成投产后预计产值；不能当环保验收或在产。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
